'use strict';
// Coche: McLaren Ultimate Vision GT / X2 (2018)
// Concepto de hiperdeportivo futurista con aerodinámica de efecto suelo activa y tracción total híbrida (V8 Twin-Turbo + motores eléctricos).
// - Carrocería de fibra de carbono completa con aerodinámica activa.
// - 4 ruedas independientes con llantas y neumáticos de competición.
// - 1150 CV y 1000 kg (relación peso/potencia extrema).
// - Atlas de texturas 2048x2048 integrado.
(() => {

const ATLAS_B64 = "data:image/png;base64,";

const BODY_V = "";
const BODY_I = "";
const GLASS_V = "";
const GLASS_I = "";
const WHEEL_V = "";
const WHEEL_I = "";


WGSL["mat_mclaren_x2"] = `// Material McLaren Ultimate Vision GT:
#include mesh_vert
@group(3) @binding(0) var tAtlas: texture_2d<f32>;

fn surf(in: V2F, ff: bool) -> Surface {
  var s = surfDefault(normalize(in.nrm));
  if (!ff) { s.normal = -s.normal; }

  let id = matId(in.mat);
  let p = in.ext.xyz;
  let uv = in.uv;

  let tx = textureSample(tAtlas, sLin, uv);
  s.albedo = tx.rgb;

  if (id == 6u) {
    // Carpaint McLaren naranja aperlado de alta reflectividad
    s.metal = 0.15;
    s.rough = 0.14;
    s.coat = 1.0;
    s.ao = smoothstep(0.05, 0.40, p.y) * 0.35 + 0.65;
  } else if (id == 4u) {
    // Fibra de carbono mate aero
    s.metal = 0.20;
    s.rough = 0.35;
    s.coat = 0.20;
  } else if (id == 5u) {
    // Llantas y neumáticos de competición
    s.metal = 0.40;
    s.rough = 0.55;
    s.ao = 0.90;
  } else if (id == 2u) {
    // Luces y detalles LED
    let brk = O.p0.x;
    s.rough = 0.10;
    s.coat = 1.0;
    if (p.x < -1.5) {
      s.emissive = mix(0.20, 1.0, brk);
    } else if (p.x > 1.5) {
      s.emissive = 0.85;
    }
  } else {
    s.metal = 0.10;
    s.rough = 0.40;
  }

  return s;
}
`;

function loadAtlas() {
  if (typeof CarFactory !== 'undefined' && typeof CarFactory.createAtlasTexture === 'function') {
    return CarFactory.createAtlasTexture(ATLAS_B64, 2048, 2048, 40);
  }
  return null;
}

const CAR = {
  id: 'mclaren-x2-2018',
  name: 'McLaren Ultimate Vision GT',
  subtitle: '2018 Vision Gran Turismo Concept · 4.0L Twin-Turbo V8 Hybrid · AWD',
  specs: '1000 kg · 1150 CV · Ground Effect Aero · Active Aero · AWD',
  accent: '#ff6600',
  physics: {
    m: 1000, Izz: 1350, L: 2.680, a: 1.340, b: 1.340, tw: 1.70, h: 0.32, R: 0.326,
    mu: 1.75, B: 12.0, C: 1.55, driveF: 0.35,
    gears: [3.98, 2.61, 1.90, 1.48, 1.16, 0.91, 0.69], final: 3.30, rev: 3.2, eff: 0.95,
    cdA: 0.55, crr: 0.010, brakeF: 0.62, halfW: 0.98, front: 2.55, rear: 2.55,
    // Aerodinámica extrema de efecto suelo + alerón trasero activo:
    clA: 1.30, aeroSplitF: 0.38,
    torqueBase: 480, torquePeak: 420, torqueDrop: 260, torquePeakStart: 0.55, torquePeakSpan: 5.5, torqueDropRpm: 8.5,
    shiftUpRpm: 8800, shiftDownRpm: 6000, revLimitRpm: 9200, maxRpm: 9500, idleRpm: 1200,
  },
  hud: { maxKmh: 420, maxRpm: 9.5, redlineRpm: 8.8 },
  wheelbase: 2.680, trackF: 1.518, trackR: 1.476, wheelR: 0.326,
  hubs: [
    [1.838, 0.326, -0.767],
    [1.838, 0.326, 0.751],
    [-1.836, 0.326, -0.745],
    [-1.836, 0.326, 0.731]
  ],
  slotBody: 0, slotWheel: [0, 0, 0, 0],
  tris: 0, _t: m4(), _t2: m4(), _t3: m4(), set: null, glass: null, atlasBG: null, fam: null,
  _z4: new Float32Array(4),
  inp: new Float64Array(2),

  build() {
    const fam = CAR.fam = mkFamily('car_mclaren_x2', { src: 'mat_mclaren_x2', noCube: true });
    CAR.slotBody = objSlot();
    for (let i = 0; i < 4; i++) CAR.slotWheel[i] = objSlot();

    const set = CAR.set = new MeshSet(fam);
    const glass = CAR.glass = new GlassSet();

    const mb = new MeshBuilder(1 << 16);
    const gl = new MeshBuilder(1 << 14);
    const w = new MeshBuilder(1 << 14);

    const bV = b64ToF32(BODY_V), bI = b64ToU16(BODY_I);
    const gV = b64ToF32(GLASS_V), gI = b64ToU16(GLASS_I);
    const wV = b64ToF32(WHEEL_V), wI = b64ToU16(WHEEL_I);

    // Unpack body
    const nbV = bV.length / 9;
    for (let i = 0; i < nbV; i++) {
      mb.mat(bV[i*9 + 8]);
      mb.v(bV[i*9], bV[i*9+1], bV[i*9+2], bV[i*9+3], bV[i*9+4], bV[i*9+5], bV[i*9+6], bV[i*9+7]);
    }
    for (let i = 0; i < bI.length; i += 3) mb.tri(bI[i], bI[i+1], bI[i+2]);

    // Unpack glass
    const ngV = gV.length / 9;
    for (let i = 0; i < ngV; i++) {
      gl.v(gV[i*9], gV[i*9+1], gV[i*9+2], gV[i*9+3], gV[i*9+4], gV[i*9+5], gV[i*9+6], gV[i*9+7]);
    }
    for (let i = 0; i < gI.length; i += 3) gl.tri(gI[i], gI[i+1], gI[i+2]);

    // Unpack wheel
    const nwV = wV.length / 9;
    for (let i = 0; i < nwV; i++) {
      w.mat(wV[i*9 + 8]);
      w.v(wV[i*9], wV[i*9+1], wV[i*9+2], wV[i*9+3], wV[i*9+4], wV[i*9+5], wV[i*9+6], wV[i*9+7]);
    }
    for (let i = 0; i < wI.length; i += 3) w.tri(wI[i], wI[i+1], wI[i+2]);

    CAR.tris = mb.ni / 3 + gl.ni / 3;
    set.add(mb.upload(), CAR.slotBody, 3);
    glass.add_(gl.upload(), CAR.slotBody);

    const wm = w.upload();
    CAR.tris += 4 * w.ni / 3;
    for (let i = 0; i < 4; i++) set.add(wm, CAR.slotWheel[i], 3);

    const tex = loadAtlas();
    R.drawables.push({
      draw(pass, ctx) {
        if (ctx.kind === KIND.SHADOW && ctx.cascade === 3) return;
        if (!CAR.atlasBG) {
          if (!fam.bgl3) return;
          CAR.atlasBG = G.dev.createBindGroup({ layout: fam.bgl3, entries: [{ binding: 0, resource: tex.createView() }] });
        }
        pass.setBindGroup(3, CAR.atlasBG);
        set.draw(pass, ctx);
      },
    });
    R.transparents.push(glass);

    m4ident(CAR._t);
    CAR.place(CAR._t, CAR._z4, CAR._z4);
    CAR.place(CAR._t, CAR._z4, CAR._z4);
  },

  place(body, spin, susp) {
    const steer = CAR.inp[0];
    const t = CAR._t2;
    objPrev(CAR.slotBody).set(objModel(CAR.slotBody));
    objModel(CAR.slotBody).set(body);
    for (let i = 0; i < 4; i++) {
      const sl = CAR.slotWheel[i], h = CAR.hubs[i], left = (i & 1) === 0;
      objPrev(sl).set(objModel(sl));
      const a = -(i < 2 ? steer : 0) + (left ? PI : 0), c = Math.cos(a), sn = Math.sin(a);
      const g = left ? spin[i] : -spin[i], cg = Math.cos(g), sg = Math.sin(g);
      t[0] = c * cg; t[1] = sg; t[2] = -sn * cg; t[3] = 0;
      t[4] = -c * sg; t[5] = cg; t[6] = sn * sg; t[7] = 0;
      t[8] = sn; t[9] = 0; t[10] = c; t[11] = 0;
      t[12] = h[0]; t[13] = h[1] + susp[i]; t[14] = h[2]; t[15] = 1;
      m4mul(objModel(sl), body, t);
    }
  },
};

CARS.register(CAR);
})();
